// Stand-in for the Paper/Bukkit API, only to compile and test XrayWatch. Not shipped.
package org.bukkit.event.player;
public class PlayerInteractEvent extends PlayerEvent implements org.bukkit.event.Cancellable { private final org.bukkit.event.block.Action a; private final org.bukkit.block.Block b; private final org.bukkit.inventory.EquipmentSlot h; private boolean cancel; public PlayerInteractEvent(org.bukkit.entity.Player p, org.bukkit.event.block.Action a, org.bukkit.block.Block b, org.bukkit.inventory.EquipmentSlot h) { super(p); this.a = a; this.b = b; this.h = h; } public org.bukkit.event.block.Action getAction() { return a; } public org.bukkit.block.Block getClickedBlock() { return b; } public org.bukkit.inventory.EquipmentSlot getHand() { return h; } public boolean isCancelled() { return cancel; } public void setCancelled(boolean c) { cancel = c; } }
